$(document).ready(function(){const e=document.getElementById("newPasswordInput"),t=document.getElementById("newRePasswordInput"),s=document.getElementById("letter"),l=document.getElementById("capital"),n=document.getElementById("number"),d=document.getElementById("length");function a(){e.value===t.value?(document.getElementById("iguality").style.display="block",document.getElementById("desiguality").style.display="none"):(document.getElementById("iguality").style.display="none",document.getElementById("desiguality").style.display="block")}e.onfocus=function(){document.getElementById("message").style.display="block"},e.onblur=function(){document.getElementById("message").style.display="none"},t.onfocus=function(){document.getElementById("messagePass").style.display="block",a()},t.onblur=function(){document.getElementById("messagePass").style.display="none"},t.onkeyup=function(){a()},e.onkeyup=function(){e.value.match(/[a-z]/g)?(s.classList.remove("invalid"),s.classList.add("valid")):(s.classList.remove("valid"),s.classList.add("invalid"));e.value.match(/[A-Z]/g)?(l.classList.remove("invalid"),l.classList.add("valid")):(l.classList.remove("valid"),l.classList.add("invalid"));e.value.match(/[0-9]/g)?(n.classList.remove("invalid"),n.classList.add("valid")):(n.classList.remove("valid"),n.classList.add("invalid")),e.value.length>=8?(d.classList.remove("invalid"),d.classList.add("valid")):(d.classList.remove("valid"),d.classList.add("invalid"))}});